-- HZad TEF Canada Listening Test01, 40 items, 40 minutes.
-- Original questions and pinned recorded audio only. All student data/credits remain untouched.
-- Requires deployed full audio and four image panels to be SHA verified before applying.
begin;
create schema academy_tef_listening;
revoke all on schema academy_tef_listening from public,anon,authenticated,service_role;
create table academy_tef_listening.papers(
 id text not null,version text not null,content jsonb not null,
 primary key(id,version),
 check(jsonb_typeof(content->'questions')='array' and jsonb_array_length(content->'questions')=40 and (content->>'seconds')::integer=2400)
);
create table academy_tef_listening.attempts(
 id uuid primary key,user_id uuid not null references auth.users(id),
 test_id text not null,version text not null,
 status text not null default 'active' check(status in ('active','completed')),
 answers jsonb not null default '{}' check(jsonb_typeof(answers)='object'),
 revision integer not null default 0,
 started_at timestamptz not null default now(),
 deadline timestamptz not null default now()+interval '40 minutes',
 submitted_at timestamptz,result jsonb,
 foreign key(test_id,version) references academy_tef_listening.papers(id,version),
 check((status='active' and submitted_at is null and result is null) or (status='completed' and submitted_at is not null and result is not null))
);
create unique index listening_one_active on academy_tef_listening.attempts(user_id,test_id,version) where status='active';
create index listening_owned_history on academy_tef_listening.attempts(user_id,started_at desc);
alter table academy_tef_listening.papers enable row level security;
alter table academy_tef_listening.attempts enable row level security;
revoke all on all tables in schema academy_tef_listening from public,anon,authenticated,service_role;
create function academy_tef_listening.freeze_paper() returns trigger language plpgsql set search_path='' as $$
begin raise exception 'Listening paper is immutable';end;$$;
create trigger listening_paper_immutable before update or delete on academy_tef_listening.papers for each row execute function academy_tef_listening.freeze_paper();
create function academy_tef_listening.freeze_identity() returns trigger language plpgsql set search_path='' as $$
begin
 if (new.id,new.user_id,new.test_id,new.version) is distinct from (old.id,old.user_id,old.test_id,old.version) then raise exception 'Listening attempt identity is immutable';end if;
 return new;
end;$$;
create trigger listening_identity_immutable before update on academy_tef_listening.attempts for each row execute function academy_tef_listening.freeze_identity();


create table academy_tef_listening.navigation(
 attempt_id uuid primary key references academy_tef_listening.attempts(id),
 skipped_seconds numeric not null check(skipped_seconds>=0 and skipped_seconds<2400)
);
alter table academy_tef_listening.navigation enable row level security;
revoke all on academy_tef_listening.navigation from public,anon,authenticated,service_role;

insert into academy_tef_listening.papers(id,version,content)
values('tef-listening-01','tef-listening-2026-11-test01-v1',$tef_data${"id":"tef-listening-01","version":"tef-listening-2026-11-test01-v1","title":"TEF Listening · Test 01","seconds":2400,"questions":[{"number":1,"kind":"picture","question":"Dans quel lieu se déroule la conversation ?","options":["À la gare, devant les consignes automatiques.","Au musée, à côté du vestiaire.","À la bibliothèque, près d’une borne de retour.","À la librairie, près du comptoir de vente."],"correct":"C","explanation":"Il s’agit de rendre des romans à une borne de retour, et non de les acheter ou de déposer des bagages.","transcript":"— Je dois rapporter ces romans aujourd’hui. — La borne de retour est près de l’entrée, juste à côté des casiers.","segments":[{"voice":"female","text":"Je dois rapporter ces romans aujourd’hui."},{"voice":"male","text":"La borne de retour est près de l’entrée, juste à côté des casiers."}],"audio":"q-01.mp3","audioSeconds":7.397,"slotSeconds":40,"previewSeconds":5,"image":"q-01.svg"},{"number":2,"kind":"picture","question":"Quelle scène correspond au dialogue ?","options":["Une cliente achète des médicaments en pharmacie.","Une cliente choisit des produits au supermarché.","Une patiente consulte un médecin à son cabinet.","Une cliente retire un colis au bureau de poste."],"correct":"A","explanation":"L’ordonnance, la disponibilité d’un médicament et les boîtes renvoient à la pharmacie.","transcript":"— Votre ordonnance est prête, mais ce médicament n’est disponible qu’en petit format. — Dans ce cas, je prendrai deux boîtes.","segments":[{"voice":"female","text":"Votre ordonnance est prête, mais ce médicament n’est disponible qu’en petit format."},{"voice":"male","text":"Dans ce cas, je prendrai deux boîtes."}],"audio":"q-02.mp3","audioSeconds":8.958,"slotSeconds":40,"previewSeconds":5,"image":"q-02.svg"},{"number":3,"kind":"picture","question":"Où sont les personnes ?","options":["À l’arrêt d’un autobus urbain.","Devant la porte d’embarquement d’un aéroport.","Au guichet d’une station de métro.","Sur le quai d’une gare ferroviaire."],"correct":"D","explanation":"La voie sept et le train pour Angers désignent un quai ferroviaire.","transcript":"— On reste sur ce quai ? — Non, le train pour Angers part désormais de la voie sept. Dépêchons-nous.","segments":[{"voice":"female","text":"On reste sur ce quai ?"},{"voice":"male","text":"Non, le train pour Angers part désormais de la voie sept. Dépêchons-nous."}],"audio":"q-03.mp3","audioSeconds":7.617,"slotSeconds":40,"previewSeconds":5,"image":"q-03.svg"},{"number":4,"kind":"picture","question":"Quelle image correspond à la situation ?","options":["Un agent accueille des spectateurs au théâtre.","Un serveur accueille des clients au restaurant.","Un employé enregistre des voyageurs à l’hôtel.","Un vendeur conseille des visiteurs dans un magasin."],"correct":"B","explanation":"La réservation d’une table et la préférence près de la fenêtre concernent un restaurant.","transcript":"— Votre réservation est à dix-neuf heures trente. Préférez-vous la table près de la fenêtre ? — Oui, si elle est encore libre.","segments":[{"voice":"female","text":"Votre réservation est à dix-neuf heures trente. Préférez-vous la table près de la fenêtre ?"},{"voice":"male","text":"Oui, si elle est encore libre."}],"audio":"q-04.mp3","audioSeconds":9.237,"slotSeconds":40,"previewSeconds":5,"image":"q-04.svg"},{"number":5,"kind":"announcement","question":"Quel élément a été modifié ?","options":["La porte d’embarquement.","L’heure de départ.","La destination du trajet.","La durée du voyage."],"correct":"A","explanation":"Le départ est maintenu ; seule la porte passe de neuf à douze.","transcript":"Attention, voyageurs à destination de Brest : le départ prévu à dix-sept heures quarante est maintenu, mais l’embarquement se fera à la porte douze au lieu de la porte neuf.","segments":[{"voice":"female","text":"Attention, voyageurs à destination de Brest : le départ prévu à dix-sept heures quarante est maintenu, mais l’embarquement se fera à la porte douze au lieu de la porte neuf."}],"audio":"q-05.mp3","audioSeconds":9.936,"slotSeconds":45,"previewSeconds":8},{"number":6,"kind":"announcement","question":"Que doivent faire les voyageurs concernés ?","options":["Prendre systématiquement la ligne suivante.","Reporter leur déplacement après vendredi.","Se rendre à un arrêt temporaire.","Attendre un bus supplémentaire à la mairie."],"correct":"C","explanation":"La ligne fonctionne mais dessert un arrêt provisoire rue des Tilleuls.","transcript":"En raison de travaux sur la chaussée, la ligne de bus vingt-quatre ne dessert pas l’arrêt Hôtel-de-Ville jusqu’à vendredi inclus. Un arrêt provisoire est installé rue des Tilleuls.","segments":[{"voice":"female","text":"En raison de travaux sur la chaussée, la ligne de bus vingt-quatre ne dessert pas l’arrêt Hôtel-de-Ville jusqu’à vendredi inclus. Un arrêt provisoire est installé rue des Tilleuls."}],"audio":"q-06.mp3","audioSeconds":10.575,"slotSeconds":45,"previewSeconds":8},{"number":7,"kind":"announcement","question":"Que précise cette annonce ?","options":["Une deuxième séance est ajoutée à vingt heures.","La représentation commencera avec un quart d’heure de retard.","Les billets doivent être échangés avant le spectacle.","La représentation est déplacée au lendemain."],"correct":"B","explanation":"Le début passe de vingt heures à vingt heures quinze sans changement des billets.","transcript":"Mesdames et messieurs, le spectacle de ce soir débutera à vingt heures quinze. Les billets pour la séance initialement prévue à vingt heures restent valables. Merci de conserver vos places.","segments":[{"voice":"female","text":"Mesdames et messieurs, le spectacle de ce soir débutera à vingt heures quinze. Les billets pour la séance initialement prévue à vingt heures restent valables. Merci de conserver vos places."}],"audio":"q-07.mp3","audioSeconds":11.631,"slotSeconds":45,"previewSeconds":8},{"number":8,"kind":"announcement","question":"Quelle restriction est annoncée ?","options":["L’ensemble du parc ferme ses portes.","La plage des Sables devient payante.","Les visites guidées sont supprimées.","Une portion du sentier n’est plus accessible."],"correct":"D","explanation":"La fermeture ne concerne que le tronçon indiqué.","transcript":"Pour des raisons de sécurité, l’accès au sentier côtier est fermé entre la pointe du Phare et la plage des Sables. Les autres itinéraires du parc restent ouverts.","segments":[{"voice":"female","text":"Pour des raisons de sécurité, l’accès au sentier côtier est fermé entre la pointe du Phare et la plage des Sables. Les autres itinéraires du parc restent ouverts."}],"audio":"q-08.mp3","audioSeconds":9.903,"slotSeconds":45,"previewSeconds":8},{"number":9,"kind":"voicemail","question":"Pourquoi appelle-t-on Madame Leblanc ?","options":["Pour lui proposer de louer un autre vélo.","Pour lui annoncer qu’elle peut récupérer son vélo.","Pour lui demander de confirmer un devis.","Pour reporter la réparation de son vélo."],"correct":"B","explanation":"La réparation est terminée, et l’appel précise l’heure limite de retrait.","transcript":"Bonjour Madame Leblanc, c’est l’atelier Vélo Plus. Votre vélo est réparé. Vous pouvez venir le récupérer dès aujourd’hui, mais l’atelier fermera exceptionnellement à seize heures.","segments":[{"voice":"female","text":"Bonjour Madame Leblanc, c’est l’atelier Vélo Plus. Votre vélo est réparé. Vous pouvez venir le récupérer dès aujourd’hui, mais l’atelier fermera exceptionnellement à seize heures."}],"audio":"q-09.mp3","audioSeconds":10.517,"slotSeconds":45,"previewSeconds":8},{"number":10,"kind":"voicemail","question":"Que propose Léo ?","options":["De déplacer le déménagement à dimanche.","D’envoyer quelqu’un à sa place le matin.","De prêter son véhicule dès la veille.","De venir aider plus tard dans la journée."],"correct":"D","explanation":"Léo remplace sa disponibilité du matin par celle de l’après-midi.","transcript":"Salut Amine, c’est Léo. Finalement, je ne pourrai pas t’aider samedi matin pour le déménagement. En revanche, je suis disponible tout l’après-midi. Dis-moi si ça t’arrange.","segments":[{"voice":"female","text":"Salut Amine, c’est Léo. Finalement, je ne pourrai pas t’aider samedi matin pour le déménagement. En revanche, je suis disponible tout l’après-midi. Dis-moi si ça t’arrange."}],"audio":"q-10.mp3","audioSeconds":10.807,"slotSeconds":45,"previewSeconds":8},{"number":11,"kind":"voicemail","question":"Quel est l’objet principal du message ?","options":["Demander de refaire un examen avant jeudi.","Préciser que le cabinet sera fermé jeudi.","Confirmer un rendez-vous et rappeler un document nécessaire.","Annoncer que l’horaire du rendez-vous a changé."],"correct":"C","explanation":"Le secrétariat confirme onze heures et demande le compte rendu existant.","transcript":"Bonjour, ici le secrétariat du cabinet Dumas. Le rendez-vous de jeudi à onze heures est confirmé. N’oubliez pas d’apporter le compte rendu de votre dernier examen médical.","segments":[{"voice":"female","text":"Bonjour, ici le secrétariat du cabinet Dumas. Le rendez-vous de jeudi à onze heures est confirmé. N’oubliez pas d’apporter le compte rendu de votre dernier examen médical."}],"audio":"q-11.mp3","audioSeconds":10.725,"slotSeconds":45,"previewSeconds":8},{"number":12,"kind":"voicemail","question":"Que doit faire Nora ?","options":["Transmettre une seule pièce manquante avant lundi.","Déposer un nouveau dossier entièrement rempli.","Appeler lundi pour obtenir un rendez-vous.","Attendre que l’organisme valide les justificatifs."],"correct":"A","explanation":"Le dossier est reçu ; seule l’attestation de stage doit être ajoutée.","transcript":"Bonsoir Nora. Nous avons bien reçu votre dossier de candidature, mais il manque une attestation de stage. Vous pouvez l’envoyer par courriel avant lundi, sans recommencer toute l’inscription.","segments":[{"voice":"female","text":"Bonsoir Nora. Nous avons bien reçu votre dossier de candidature, mais il manque une attestation de stage. Vous pouvez l’envoyer par courriel avant lundi, sans recommencer toute l’inscription."}],"audio":"q-12.mp3","audioSeconds":11.318,"slotSeconds":45,"previewSeconds":8},{"number":13,"kind":"street","question":"Quelle est la position de cette personne ?","options":["Elle refuse toute ouverture dominicale.","Elle soutient l’ouverture sans condition particulière.","Elle ne souhaite pas se prononcer.","Elle est favorable, sous réserve de garanties pour le personnel."],"correct":"D","explanation":"Elle est favorable, mais exige des garanties pour les employés.","transcript":"— Pensez-vous qu’il faudrait ouvrir les bibliothèques le dimanche ? — Personnellement, je suis favorable à cette idée, à condition que les employés puissent choisir leurs horaires et obtenir une compensation.","segments":[{"voice":"female","text":"Pensez-vous qu’il faudrait ouvrir les bibliothèques le dimanche ?"},{"voice":"male","text":"Personnellement, je suis favorable à cette idée, à condition que les employés puissent choisir leurs horaires et obtenir une compensation."}],"audio":"q-13.mp3","audioSeconds":11.745,"slotSeconds":50,"previewSeconds":8},{"number":14,"kind":"street","question":"Que pense cette personne du vélo au quotidien ?","options":["Elle hésite parce qu’elle ignore les itinéraires.","Elle considère qu’il ne convient pas à ses besoins professionnels.","Elle l’utiliserait si les pistes cyclables étaient améliorées.","Elle compte le privilégier pour tous ses déplacements."],"correct":"B","explanation":"Le matériel lourd empêche ce changement, même avec de meilleures pistes.","transcript":"— Seriez-vous prêt à remplacer votre voiture par un vélo ? — Franchement non. Même avec de bonnes pistes cyclables, mon travail m’oblige à transporter du matériel lourd presque tous les jours.","segments":[{"voice":"female","text":"Seriez-vous prêt à remplacer votre voiture par un vélo ?"},{"voice":"male","text":"Franchement non. Même avec de bonnes pistes cyclables, mon travail m’oblige à transporter du matériel lourd presque tous les jours."}],"audio":"q-14.mp3","audioSeconds":12.28,"slotSeconds":50,"previewSeconds":8},{"number":15,"kind":"street","question":"Quelle opinion est exprimée ?","options":["Une approbation conditionnée par le choix et la diversité.","Un rejet de toute proposition végétarienne.","Une adhésion à un menu identique pour tous.","Une absence d’avis sur les repas servis."],"correct":"A","explanation":"La personne apprécie l’idée mais défend la variété et le libre choix.","transcript":"— Les repas végétariens à la cantine, vous en pensez quoi ? — Cela me semble intéressant, mais il faut surtout proposer des plats variés et ne pas imposer la même formule à tout le monde.","segments":[{"voice":"female","text":"Les repas végétariens à la cantine, vous en pensez quoi ?"},{"voice":"male","text":"Cela me semble intéressant, mais il faut surtout proposer des plats variés et ne pas imposer la même formule à tout le monde."}],"audio":"q-15.mp3","audioSeconds":12.168,"slotSeconds":50,"previewSeconds":8},{"number":16,"kind":"street","question":"Quelle est la position de cette personne ?","options":["Elle accepte la publicité si elle est lumineuse.","Elle évite de donner un avis personnel.","Elle soutient une réduction de la publicité.","Elle défend davantage de panneaux commerciaux."],"correct":"C","explanation":"Elle veut remplacer la publicité envahissante par des informations utiles.","transcript":"— Faut-il limiter la publicité dans les transports ? — Absolument. Les panneaux lumineux sont trop envahissants, et je préférerais qu’on utilise cet espace pour des informations pratiques.","segments":[{"voice":"female","text":"Faut-il limiter la publicité dans les transports ?"},{"voice":"male","text":"Absolument. Les panneaux lumineux sont trop envahissants, et je préférerais qu’on utilise cet espace pour des informations pratiques."}],"audio":"q-16.mp3","audioSeconds":11.263,"slotSeconds":50,"previewSeconds":8},{"number":17,"kind":"street","question":"Quelle appréciation porte cette personne ?","options":["Les cours en salle devraient disparaître rapidement.","Elle ne distingue aucun avantage entre les formats.","Les cours en ligne sont utiles sans suffire dans tous les cas.","Les cours en ligne lui paraissent toujours supérieurs."],"correct":"C","explanation":"Elle apprécie les révisions en ligne mais privilégie l’échange pour les sujets complexes.","transcript":"— Les cours en ligne remplacent-ils bien les cours en salle ? — Pas complètement. Pour les révisions, c’est pratique, mais j’ai besoin d’échanger en direct avec le professeur lorsque le sujet devient complexe.","segments":[{"voice":"female","text":"Les cours en ligne remplacent-ils bien les cours en salle ?"},{"voice":"male","text":"Pas complètement. Pour les révisions, c’est pratique, mais j’ai besoin d’échanger en direct avec le professeur lorsque le sujet devient complexe."}],"audio":"q-17.mp3","audioSeconds":11.919,"slotSeconds":50,"previewSeconds":8},{"number":18,"kind":"street","question":"Quel bénéfice la personne met-elle surtout en avant ?","options":["La diminution du temps consacré au jardinage.","Les rencontres créées entre habitants.","Les économies réalisées sur tous les achats.","La possibilité de vendre ses récoltes."],"correct":"B","explanation":"Le mot surtout introduit l’avantage relationnel.","transcript":"— Que pensez-vous des jardins partagés ? — J’y vais déjà deux fois par semaine. J’ai appris à cultiver des légumes et, surtout, j’y ai rencontré des voisins que je ne connaissais pas.","segments":[{"voice":"female","text":"Que pensez-vous des jardins partagés ?"},{"voice":"male","text":"J’y vais déjà deux fois par semaine. J’ai appris à cultiver des légumes et, surtout, j’y ai rencontré des voisins que je ne connaissais pas."}],"audio":"q-18.mp3","audioSeconds":11.78,"slotSeconds":50,"previewSeconds":8},{"number":19,"kind":"street","question":"Quelle mesure cette personne défend-elle ?","options":["Une gratuité ciblée plutôt qu’une suppression générale des tarifs.","Une entrée gratuite sans limite d’âge ni budget.","Une augmentation des tarifs réservée aux jeunes.","Le maintien intégral des prix actuels."],"correct":"A","explanation":"Elle distingue la gratuité pour les jeunes d’une mesure universelle difficile à financer.","transcript":"— Est-ce que les musées devraient être gratuits ? — Oui, pour les moins de vingt-six ans, certainement. Mais une gratuité générale demanderait des financements que nous n’avons pas encore garantis.","segments":[{"voice":"female","text":"Est-ce que les musées devraient être gratuits ?"},{"voice":"male","text":"Oui, pour les moins de vingt-six ans, certainement. Mais une gratuité générale demanderait des financements que nous n’avons pas encore garantis."}],"audio":"q-19.mp3","audioSeconds":11.849,"slotSeconds":50,"previewSeconds":8},{"number":20,"kind":"street","question":"Quelle organisation préconise la personne ?","options":["Un télétravail permanent dès l’embauche.","Une présence obligatoire au bureau chaque jour.","Une suspension du télétravail pour tout le personnel.","Une formule hybride avec présence régulière au bureau."],"correct":"D","explanation":"Elle propose deux jours à distance et un accompagnement présentiel.","transcript":"— L’entreprise devrait-elle généraliser le télétravail ? — Je ne suis pas opposée à cette possibilité, mais les nouveaux salariés ont besoin de rencontrer leurs équipes. Deux jours à distance seraient raisonnables.","segments":[{"voice":"female","text":"L’entreprise devrait-elle généraliser le télétravail ?"},{"voice":"male","text":"Je ne suis pas opposée à cette possibilité, mais les nouveaux salariés ont besoin de rencontrer leurs équipes. Deux jours à distance seraient raisonnables."}],"audio":"q-20.mp3","audioSeconds":12.888,"slotSeconds":50,"previewSeconds":8},{"number":21,"kind":"radio","question":"Quelle limite le chroniqueur souligne-t-il ?","options":["La demande augmente plus vite que les capacités des ateliers.","Les habitants se désintéressent des objets réparables.","Les réparations coûtent désormais plus cher que les appareils neufs.","Les ateliers cherchent à limiter l’accès aux habitants du quartier."],"correct":"A","explanation":"Le chroniqueur évoque une demande croissante que les effectifs actuels peinent à satisfaire.","transcript":"Vous écoutez notre chronique économique. Depuis l’ouverture d’ateliers de réparation dans plusieurs quartiers, les habitants conservent leurs appareils plus longtemps. L’intérêt n’est pas seulement écologique : certains réparateurs expliquent que les demandes affluent, sans que les nouveaux emplois soient encore assez nombreux pour répondre à tous les besoins.","segments":[{"voice":"female","text":"Vous écoutez notre chronique économique. Depuis l’ouverture d’ateliers de réparation dans plusieurs quartiers, les habitants conservent leurs appareils plus longtemps. L’intérêt n’est pas seulement écologique : certains réparateurs expliquent que les demandes affluent, sans que les nouveaux emplois soient encore assez nombreux pour répondre à tous les besoins."}],"audio":"q-21.mp3","audioSeconds":18.144,"slotSeconds":65,"previewSeconds":10},{"number":22,"kind":"radio","question":"Pourquoi les ingénieurs restent-ils prudents ?","options":["La baisse de consommation n’a jamais été constatée.","Les écoles ont refusé toute installation supplémentaire.","Le système ne fonctionne que pendant les périodes de sécheresse.","Les observations sont trop dépendantes du climat pour conclure rapidement."],"correct":"D","explanation":"Les résultats initiaux sont encourageants, mais insuffisants pour juger la rentabilité annuelle.","transcript":"La municipalité a testé un système de récupération des eaux de pluie sur trois écoles. Les premiers chiffres montrent une diminution de la consommation d’eau potable. Toutefois, les ingénieurs rappellent que les résultats dépendent fortement de la saison et du niveau des précipitations ; une année suffit mal pour mesurer la rentabilité du dispositif.","segments":[{"voice":"female","text":"La municipalité a testé un système de récupération des eaux de pluie sur trois écoles. Les premiers chiffres montrent une diminution de la consommation d’eau potable. Toutefois, les ingénieurs rappellent que les résultats dépendent fortement de la saison et du niveau des précipitations ; une année suffit mal pour mesurer la rentabilité du dispositif."}],"audio":"q-22.mp3","audioSeconds":19.27,"slotSeconds":65,"previewSeconds":10},{"number":23,"kind":"interview","question":"Quel motif a principalement guidé le changement de lieu ?","options":["Développer les ventes uniquement grâce au tramway.","Rendre le marché plus accessible à différents publics.","Accueillir davantage de commerçants venus de l’étranger.","Réduire la durée d’ouverture quotidienne du marché."],"correct":"B","explanation":"La décision répond d’abord aux difficultés d’accès et non à une stratégie commerciale.","transcript":"— Pourquoi avoir déplacé le marché de producteurs ? — La place centrale était devenue difficile d’accès aux personnes à mobilité réduite. Le nouveau site est un peu plus loin, mais il dispose d’allées larges et d’un arrêt de tramway à proximité.","segments":[{"voice":"female","text":"Pourquoi avoir déplacé le marché de producteurs ?"},{"voice":"male","text":"La place centrale était devenue difficile d’accès aux personnes à mobilité réduite. Le nouveau site est un peu plus loin, mais il dispose d’allées larges et d’un arrêt de tramway à proximité."}],"audio":"q-23.mp3","audioSeconds":15.146,"slotSeconds":65,"previewSeconds":10},{"number":24,"kind":"interview","question":"Quelle réserve est mentionnée ?","options":["L’ensemble des producteurs réclame un retour immédiat.","Les résultats définitifs sont déjà connus après trois mois.","La nouvelle implantation pourrait réduire les achats de passage.","Les livraisons deviennent impossibles sur le nouveau site."],"correct":"C","explanation":"Les inquiétudes portent sur la clientèle spontanée ; les ventes restent à évaluer.","transcript":"— Ce déplacement a-t-il convaincu les commerçants ? — Pas tous. Les producteurs apprécient l’espace de chargement, mais certains craignent de perdre les clients qui fréquentaient spontanément l’ancienne place. Nous suivrons les ventes pendant trois mois avant de trancher.","segments":[{"voice":"female","text":"Ce déplacement a-t-il convaincu les commerçants ?"},{"voice":"male","text":"Pas tous. Les producteurs apprécient l’espace de chargement, mais certains craignent de perdre les clients qui fréquentaient spontanément l’ancienne place. Nous suivrons les ventes pendant trois mois avant de trancher."}],"audio":"q-24.mp3","audioSeconds":15.843,"slotSeconds":65,"previewSeconds":10},{"number":25,"kind":"interview","question":"Quelle évolution l’association a-t-elle adoptée ?","options":["Un apprentissage sans utilisation d’appareils personnels.","Un accompagnement fondé sur les besoins individuels.","Un programme unique avec les mêmes exercices pour tous.","Des ateliers réservés exclusivement à la cybersécurité."],"correct":"B","explanation":"Les séances partent d’une difficulté précise de chaque participant.","transcript":"— Votre association propose des ateliers numériques aux personnes âgées. Qu’est-ce qui a changé ? — Nous avons abandonné les cours identiques pour tous. Désormais, chacun vient avec une difficulté concrète : envoyer une photo, réserver un billet ou protéger son compte.","segments":[{"voice":"female","text":"Votre association propose des ateliers numériques aux personnes âgées. Qu’est-ce qui a changé ?"},{"voice":"male","text":"Nous avons abandonné les cours identiques pour tous. Désormais, chacun vient avec une difficulté concrète : envoyer une photo, réserver un billet ou protéger son compte."}],"audio":"q-25.mp3","audioSeconds":16.958,"slotSeconds":65,"previewSeconds":10},{"number":26,"kind":"interview","question":"Quel résultat la responsable observe-t-elle ?","options":["Une aide plus ciblée qui limite la répétition des mêmes demandes.","Une réduction du nombre de bénévoles nécessaires à chaque séance.","Une hausse des visites provoquée par des fiches trop complexes.","La disparition du besoin de préparer les ateliers."],"correct":"A","explanation":"L’approche mobilise des petits groupes et évite de traiter plusieurs fois la même difficulté.","transcript":"— Est-ce que cette méthode demande davantage de bénévoles ? — Oui, mais pas nécessairement plus d’heures. Nous accueillons des groupes plus petits et préparons de courtes fiches pratiques. Les participants reviennent moins souvent pour le même problème.","segments":[{"voice":"female","text":"Est-ce que cette méthode demande davantage de bénévoles ?"},{"voice":"male","text":"Oui, mais pas nécessairement plus d’heures. Nous accueillons des groupes plus petits et préparons de courtes fiches pratiques. Les participants reviennent moins souvent pour le même problème."}],"audio":"q-26.mp3","audioSeconds":14.461,"slotSeconds":65,"previewSeconds":10},{"number":27,"kind":"interview","question":"Quelle faiblesse des moyennes est mise en évidence ?","options":["Elles exagèrent toujours le niveau sonore d’un quartier.","Elles excluent les zones scolaires de toute mesure.","Elles ne permettent jamais de comparer deux quartiers.","Elles masquent la répartition du bruit selon les lieux et les horaires."],"correct":"D","explanation":"La même moyenne peut correspondre à des expositions très différentes.","transcript":"— Vous étudiez le bruit en ville. Pourquoi les moyennes ne vous suffisent-elles pas ? — Deux quartiers peuvent afficher le même niveau moyen, mais dans l’un les nuisances durent toute la journée, alors que dans l’autre elles se concentrent près d’une école à la sortie des classes.","segments":[{"voice":"female","text":"Vous étudiez le bruit en ville. Pourquoi les moyennes ne vous suffisent-elles pas ?"},{"voice":"male","text":"Deux quartiers peuvent afficher le même niveau moyen, mais dans l’un les nuisances durent toute la journée, alors que dans l’autre elles se concentrent près d’une école à la sortie des classes."}],"audio":"q-27.mp3","audioSeconds":14.258,"slotSeconds":65,"previewSeconds":10},{"number":28,"kind":"interview","question":"Quelle méthode la chercheuse recommande-t-elle ?","options":["Remplacer les données chiffrées par les seules plaintes.","Comparer les quartiers sans tenir compte des horaires.","Associer les mesures à des informations sur les usages et les habitants.","Se fonder exclusivement sur les classements acoustiques."],"correct":"C","explanation":"La chercheuse veut combiner mesures, usages et témoignages.","transcript":"— Comment votre étude peut-elle aider les décideurs ? — Plutôt qu’un classement unique des quartiers, nous recommandons de croiser les mesures sonores avec les horaires de fréquentation et les plaintes recueillies auprès des habitants.","segments":[{"voice":"female","text":"Comment votre étude peut-elle aider les décideurs ?"},{"voice":"male","text":"Plutôt qu’un classement unique des quartiers, nous recommandons de croiser les mesures sonores avec les horaires de fréquentation et les plaintes recueillies auprès des habitants."}],"audio":"q-28.mp3","audioSeconds":12.023,"slotSeconds":65,"previewSeconds":10},{"number":29,"kind":"report","question":"Quel enjeu demeure malgré le succès du projet ?","options":["Le manque d’intérêt de la population locale.","L’impossibilité d’accéder à une aide administrative.","La fermeture prochaine des ateliers proposés.","La maîtrise des dépenses de fonctionnement."],"correct":"D","explanation":"Le lieu est fréquenté, mais la facture de chauffage dépasse les prévisions.","transcript":"Dans une petite commune des Alpes, une ancienne poste a été transformée en espace de services. On peut y rencontrer une conseillère administrative, emprunter des outils et participer à des ateliers. Les élus saluent l’affluence, tout en reconnaissant que le coût de chauffage du bâtiment reste plus élevé que prévu.","segments":[{"voice":"female","text":"Dans une petite commune des Alpes, une ancienne poste a été transformée en espace de services. On peut y rencontrer une conseillère administrative, emprunter des outils et participer à des ateliers. Les élus saluent l’affluence, tout en reconnaissant que le coût de chauffage du bâtiment reste plus élevé que prévu."}],"audio":"q-29.mp3","audioSeconds":17.413,"slotSeconds":65,"previewSeconds":10},{"number":30,"kind":"report","question":"Pourquoi un accueil sur place est-il conservé ?","options":["Pour réserver les démarches aux personnes âgées.","Pour vérifier systématiquement toutes les demandes déjà validées.","Pour éviter que le numérique ne prive certains habitants du service.","Pour supprimer progressivement les demandes en ligne."],"correct":"C","explanation":"La présence humaine répond aux difficultés d’accès et d’autonomie numérique.","transcript":"Les habitants peuvent désormais déposer une demande en ligne, mais la commune maintient un accueil physique deux matinées par semaine. Selon la responsable du projet, la dématérialisation ne doit pas exclure les personnes qui disposent d’une connexion limitée ou qui ont besoin d’être accompagnées.","segments":[{"voice":"female","text":"Les habitants peuvent désormais déposer une demande en ligne, mais la commune maintient un accueil physique deux matinées par semaine. Selon la responsable du projet, la dématérialisation ne doit pas exclure les personnes qui disposent d’une connexion limitée ou qui ont besoin d’être accompagnées."}],"audio":"q-30.mp3","audioSeconds":17.053,"slotSeconds":65,"previewSeconds":10},{"number":31,"kind":"document","question":"Quelle limite méthodologique est reconnue ?","options":["Les auteurs ont déjà observé toutes les pratiques quotidiennes.","Les perceptions recueillies ne renseignent pas directement sur le travail effectué.","Les salariés interrogés n’ont pas indiqué leur satisfaction.","Les horaires flexibles n’ont été expérimentés dans aucune entreprise."],"correct":"B","explanation":"L’enquête mesure la satisfaction déclarée, pas la charge de travail réelle.","transcript":"Une recherche sur les horaires flexibles a interrogé des salariés de plusieurs entreprises. Les réponses montrent une satisfaction accrue, mais l’étude ne mesure pas l’évolution réelle de leur charge de travail. Les auteurs recommandent donc de compléter les questionnaires par une observation des pratiques.","segments":[{"voice":"female","text":"Une recherche sur les horaires flexibles a interrogé des salariés de plusieurs entreprises. Les réponses montrent une satisfaction accrue, mais l’étude ne mesure pas l’évolution réelle de leur charge de travail. Les auteurs recommandent donc de compléter les questionnaires par une observation des pratiques."}],"audio":"q-31.mp3","audioSeconds":16.287,"slotSeconds":83,"previewSeconds":10},{"number":32,"kind":"document","question":"Quel biais la journaliste dénonce-t-elle ?","options":["Les personnes ayant abandonné le service sont absentes des évaluations.","Les utilisateurs réguliers sont systématiquement défavorables à l’application.","Les statistiques s’appuient uniquement sur des données financières.","Les démarches anciennes ont déjà toutes été supprimées."],"correct":"A","explanation":"Les questionnaires des utilisateurs actifs excluent ceux qui ont renoncé.","transcript":"Dans son éditorial, la journaliste rappelle que le succès d’une application ne prouve pas à lui seul qu’elle simplifie les démarches. Les usagers qui ont renoncé après une difficulté technique ne figurent souvent pas dans les statistiques de satisfaction, calculées auprès des seuls utilisateurs actifs.","segments":[{"voice":"female","text":"Dans son éditorial, la journaliste rappelle que le succès d’une application ne prouve pas à lui seul qu’elle simplifie les démarches. Les usagers qui ont renoncé après une difficulté technique ne figurent souvent pas dans les statistiques de satisfaction, calculées auprès des seuls utilisateurs actifs."}],"audio":"q-32.mp3","audioSeconds":15.811,"slotSeconds":83,"previewSeconds":10},{"number":33,"kind":"document","question":"Sur quel point les spécialistes se rejoignent-ils ?","options":["La sélection des arbres doit tenir compte du milieu où ils seront plantés.","La plantation d’arbres doit être arrêtée dans tous les centres-villes.","Les espèces qui demandent beaucoup d’eau conviennent partout.","L’effet des arbres sur la chaleur urbaine reste entièrement inconnu."],"correct":"A","explanation":"Ils défendent la végétalisation mais insistent sur son adaptation aux sols et au climat.","transcript":"Lors d’une table ronde, un urbaniste estime que planter des arbres est essentiel pour lutter contre la chaleur. Une hydrologue lui répond que certaines espèces, mal adaptées au sol, consomment trop d’eau et risquent de dépérir. Tous deux s’accordent sur l’importance de choisir les végétaux selon les conditions locales.","segments":[{"voice":"female","text":"Lors d’une table ronde, un urbaniste estime que planter des arbres est essentiel pour lutter contre la chaleur. Une hydrologue lui répond que certaines espèces, mal adaptées au sol, consomment trop d’eau et risquent de dépérir. Tous deux s’accordent sur l’importance de choisir les végétaux selon les conditions locales."}],"audio":"q-33.mp3","audioSeconds":18.945,"slotSeconds":83,"previewSeconds":10},{"number":34,"kind":"document","question":"Quelle stratégie la directrice privilégie-t-elle ?","options":["Réserver les places à l’avance aux seuls spectateurs habituels.","Maintenir plusieurs modalités de réservation selon les publics.","Supprimer les billets individuels pour garantir les recettes.","Abandonner les abonnements au profit d’une tarification unique."],"correct":"B","explanation":"Elle oppose les préférences des publics sans vouloir supprimer une formule.","transcript":"La directrice d’un théâtre reconnaît que les abonnements annuels rassurent les équipes sur leurs recettes. Cependant, elle observe que les personnes qui découvrent le lieu préfèrent souvent acheter un billet isolé. Elle souhaite conserver les deux formules plutôt que favoriser systématiquement l’une d’elles.","segments":[{"voice":"female","text":"La directrice d’un théâtre reconnaît que les abonnements annuels rassurent les équipes sur leurs recettes. Cependant, elle observe que les personnes qui découvrent le lieu préfèrent souvent acheter un billet isolé. Elle souhaite conserver les deux formules plutôt que favoriser systématiquement l’une d’elles."}],"audio":"q-34.mp3","audioSeconds":15.996,"slotSeconds":83,"previewSeconds":10},{"number":35,"kind":"document","question":"Quel compromis est envisagé ?","options":["Ne transporter que les personnes inscrites plusieurs semaines avant.","Remplacer les trajets du marché par une application payante.","Expérimenter un trajet régulier certains jours pour compléter les réservations.","Supprimer le service à la demande dans toutes les communes."],"correct":"C","explanation":"La liaison fixe les jours de marché répond en partie au besoin de spontanéité.","transcript":"Au sujet des transports ruraux, un élu fait valoir qu’un minibus sur réservation évite des trajets à vide. Une représentante associative objecte que la réservation préalable est difficile pour les déplacements imprévus. Ils conviennent de tester une liaison fixe les jours de marché.","segments":[{"voice":"female","text":"Au sujet des transports ruraux, un élu fait valoir qu’un minibus sur réservation évite des trajets à vide. Une représentante associative objecte que la réservation préalable est difficile pour les déplacements imprévus. Ils conviennent de tester une liaison fixe les jours de marché."}],"audio":"q-35.mp3","audioSeconds":16.31,"slotSeconds":83,"previewSeconds":10},{"number":36,"kind":"document","question":"Pourquoi l’augmentation des dons ne suffit-elle pas ?","options":["Les produits frais représentent déjà la majorité des dons.","Les associations ne disposent plus d’aucune capacité de stockage.","Les producteurs locaux refusent désormais toute collaboration.","Le volume supplémentaire ne garantit pas un assortiment équilibré."],"correct":"D","explanation":"La quantité augmente surtout grâce à des aliments secs, pas grâce à une meilleure variété.","transcript":"Les responsables d’une banque alimentaire constatent que les quantités de produits reçus ont augmenté, sans que la diversité nutritionnelle progresse autant. Les dons comportent davantage de denrées sèches, mais peu de produits frais. Ils souhaitent mieux coordonner les collectes avec les producteurs voisins.","segments":[{"voice":"female","text":"Les responsables d’une banque alimentaire constatent que les quantités de produits reçus ont augmenté, sans que la diversité nutritionnelle progresse autant. Les dons comportent davantage de denrées sèches, mais peu de produits frais. Ils souhaitent mieux coordonner les collectes avec les producteurs voisins."}],"audio":"q-36.mp3","audioSeconds":16.426,"slotSeconds":83,"previewSeconds":10},{"number":37,"kind":"document","question":"Comment l’historienne traite-t-elle les contradictions ?","options":["Elle considère les archives officielles comme nécessairement fausses.","Elle classe les témoins selon leur ancienneté dans la commune.","Elle les examine en croisant témoignages et documents vérifiables.","Elle conserve uniquement le récit le plus largement partagé."],"correct":"C","explanation":"Les contradictions sont vérifiées par confrontation aux photos et archives.","transcript":"Une historienne étudie les souvenirs recueillis après une inondation. Elle remarque que plusieurs témoignages se contredisent sur l’ordre des événements. Au lieu d’écarter ces récits, elle les confronte aux photographies datées et aux archives municipales pour comprendre ces différences.","segments":[{"voice":"female","text":"Une historienne étudie les souvenirs recueillis après une inondation. Elle remarque que plusieurs témoignages se contredisent sur l’ordre des événements. Au lieu d’écarter ces récits, elle les confronte aux photographies datées et aux archives municipales pour comprendre ces différences."}],"audio":"q-37.mp3","audioSeconds":15.683,"slotSeconds":83,"previewSeconds":10},{"number":38,"kind":"document","question":"Quelle mise en garde est formulée ?","options":["Une meilleure isolation provoque toujours une hausse de consommation.","Les travaux n’apportent aucun avantage sur le plan thermique.","Les économies dépendent uniquement du prix de l’électricité.","Le comportement des occupants peut réduire une partie des économies attendues."],"correct":"D","explanation":"Les économies théoriques peuvent être atténuées par un changement des usages.","transcript":"Dans un débat sur la rénovation énergétique, une architecte explique que l’isolation réduit les besoins de chauffage. Un sociologue rappelle toutefois que certains occupants augmentent alors la température de leur logement, ce qui peut diminuer l’économie réellement observée.","segments":[{"voice":"female","text":"Dans un débat sur la rénovation énergétique, une architecte explique que l’isolation réduit les besoins de chauffage. Un sociologue rappelle toutefois que certains occupants augmentent alors la température de leur logement, ce qui peut diminuer l’économie réellement observée."}],"audio":"q-38.mp3","audioSeconds":15.044,"slotSeconds":83,"previewSeconds":10},{"number":39,"kind":"document","question":"Sur quoi porte la négociation ?","options":["Réaliser une expertise environnementale sans bloquer durablement le calendrier.","Renoncer au projet pour préserver l’ensemble des infrastructures actuelles.","Commencer les travaux sans examiner leurs conséquences sur la biodiversité.","Confier aux associations la décision finale sans intervention municipale."],"correct":"A","explanation":"La discussion concerne une évaluation préalable compatible avec un calendrier de décision.","transcript":"Le maire présente un projet de réouverture d’un ancien canal à la promenade. Les associations patrimoniales le soutiennent, mais demandent un suivi écologique indépendant avant les travaux. Le maire accepte cette évaluation, tout en refusant de reporter indéfiniment la décision.","segments":[{"voice":"female","text":"Le maire présente un projet de réouverture d’un ancien canal à la promenade. Les associations patrimoniales le soutiennent, mais demandent un suivi écologique indépendant avant les travaux. Le maire accepte cette évaluation, tout en refusant de reporter indéfiniment la décision."}],"audio":"q-39.mp3","audioSeconds":15.741,"slotSeconds":83,"previewSeconds":10},{"number":40,"kind":"document","question":"Quelle priorité les bénévoles défendent-ils ?","options":["Réduire progressivement les activités déjà appréciées du public.","Assurer la stabilité des activités avant d’en augmenter le nombre.","Créer immédiatement de nouveaux ateliers sans équipes permanentes.","Privilégier exclusivement les nouveaux visiteurs occasionnels."],"correct":"B","explanation":"Ils souhaitent consolider les moyens et l’accueil avant toute extension.","transcript":"Lorsqu’on leur demande si le centre culturel doit multiplier les activités, les bénévoles répondent qu’il vaut mieux consolider les ateliers existants. Ils craignent qu’une expansion rapide repose sur des engagements informels et fragilise l’accueil des participants les plus réguliers.","segments":[{"voice":"female","text":"Lorsqu’on leur demande si le centre culturel doit multiplier les activités, les bénévoles répondent qu’il vaut mieux consolider les ateliers existants. Ils craignent qu’une expansion rapide repose sur des engagements informels et fragilise l’accueil des participants les plus réguliers."}],"audio":"q-40.mp3","audioSeconds":16.472,"slotSeconds":83,"previewSeconds":10}]}$tef_data$::jsonb);
create function academy_tef_listening.grade(p_paper jsonb,p_answers jsonb) returns jsonb
language sql immutable set search_path='' as $$
 select jsonb_build_object(
 'correct',count(*) filter(where p_answers->>(q->>'number')=q->>'correct'),'total',count(*),
 'percentage',round(100.0*count(*) filter(where p_answers->>(q->>'number')=q->>'correct')/count(*),2),
 'unanswered',count(*) filter(where not (p_answers ? (q->>'number'))),
 'rows',jsonb_agg(jsonb_build_object('number',q->'number','selected',p_answers->(q->>'number'),'correct',q->>'correct',
 'isCorrect',coalesce(p_answers->>(q->>'number')=q->>'correct',false),'explanation',q->>'explanation','transcript',q->>'transcript') order by (q->>'number')::int))
 from jsonb_array_elements(p_paper->'questions') q;
$$;


create or replace function public.academy_tef_listening_command(p_action text,p_id uuid default null,p_payload jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare
 u uuid:=auth.uid();a academy_tef_listening.attempts;paper jsonb;history jsonb;
 question_no text;choice text;current_no integer;slot_start numeric;slot_end numeric;
 elapsed numeric;skipped numeric;question_start timestamptz;question_end timestamptz;
begin
 perform academy_ai.require_access(u);
 if p_action is null or p_action not in ('catalog','start','read','answer','next','submit') or p_payload is null or jsonb_typeof(p_payload)<>'object' or octet_length(p_payload::text)>1000 then raise exception 'Invalid listening action';end if;
 if exists(select 1 from jsonb_object_keys(p_payload) k where not (k=any(case p_action when 'start' then array['testId','version'] when 'answer' then array['number','choice','revision'] when 'next' then array['number','revision'] when 'submit' then array['revision'] else array[]::text[] end))) then raise exception 'Invalid listening request';end if;
 if p_action='catalog' then
  select coalesce(jsonb_agg(to_jsonb(h) order by h."startedAt" desc),'[]') into history from (
   select id,test_id "testId",version,status,started_at "startedAt",deadline from academy_tef_listening.attempts where user_id=u order by started_at desc limit 50) h;
  return jsonb_build_object('tests',(select jsonb_agg(jsonb_build_object('id',id,'version',version,'title',content->>'title','questions',40,'seconds',2400) order by id) from academy_tef_listening.papers),'history',history,'serverNow',now());
 end if;
 if p_id is null then raise exception 'Invalid listening attempt';end if;
 if p_action='start' then perform 1 from auth.users where id=u for update;end if;
 select * into a from academy_tef_listening.attempts where id=p_id for update;
 if found and a.user_id<>u then raise exception 'Listening attempt not found' using errcode='42501';end if;
 if p_action='start' then
  if p_payload->>'testId' is distinct from 'tef-listening-01' or p_payload->>'version' is distinct from 'tef-listening-2026-11-test01-v1' then raise exception 'Listening paper changed. Refresh before starting';end if;
  if a.id is not null and (a.test_id<>p_payload->>'testId' or a.version<>p_payload->>'version') then raise exception 'Listening attempt already used';end if;
  if a.id is null then
   update academy_tef_listening.attempts t set status='completed',submitted_at=t.deadline,result=academy_tef_listening.grade(p.content,t.answers),revision=t.revision+1
    from academy_tef_listening.papers p where t.user_id=u and t.status='active' and now()>=t.deadline and p.id=t.test_id and p.version=t.version;
   select * into a from academy_tef_listening.attempts where user_id=u and status='active' and test_id=p_payload->>'testId' and version=p_payload->>'version' for update;
   if a.id is null then insert into academy_tef_listening.attempts(id,user_id,test_id,version) values(p_id,u,p_payload->>'testId',p_payload->>'version') returning * into a;end if;
  end if;
 end if;
 if a.id is null then raise exception 'Listening attempt not found' using errcode='42501';end if;
 select content into paper from academy_tef_listening.papers where id=a.test_id and version=a.version;
 if a.status='active' and now()>=a.deadline then
  update academy_tef_listening.attempts set status='completed',submitted_at=deadline,result=academy_tef_listening.grade(paper,answers),revision=revision+1 where id=a.id returning * into a;
 end if;
 if a.status='active' then
  select coalesce((select n.skipped_seconds from academy_tef_listening.navigation n where n.attempt_id=a.id),0) into skipped;
  elapsed:=greatest(0,extract(epoch from now()-a.started_at))+skipped;
  select s.number,s.finish-s.duration,s.finish into current_no,slot_start,slot_end from (
   select (q->>'number')::int number,(q->>'slotSeconds')::numeric duration,
    sum((q->>'slotSeconds')::numeric) over(order by (q->>'number')::int) finish
   from jsonb_array_elements(paper->'questions') q) s where elapsed>=s.finish-s.duration and (elapsed<s.finish or s.number=40) order by s.number limit 1;
  if current_no is null then raise exception 'Listening timing unavailable. Reload your saved test';end if;
  question_start:=a.started_at+(slot_start-skipped)*interval '1 second';
  question_end:=case when current_no=40 then a.deadline else least(a.deadline,a.started_at+(slot_end-skipped)*interval '1 second') end;
 end if;
 if a.status='active' and p_action in ('answer','next','submit') then
  if p_payload->'revision' is distinct from to_jsonb(a.revision) then raise exception 'Listening answers changed in another tab. Reload saved answers';end if;
  if p_action='answer' then
   if jsonb_typeof(p_payload->'number') is distinct from 'number' or p_payload->>'number' !~ '^([1-9]|[12][0-9]|3[0-9]|40)$' or not (p_payload ? 'choice') or (p_payload->'choice'<>'null'::jsonb and (jsonb_typeof(p_payload->'choice')<>'string' or p_payload->>'choice' not in ('A','B','C','D'))) then raise exception 'Invalid listening choice';end if;
   if (p_payload->>'number')::int<>current_no then raise exception 'This listening question has ended. Continue with the current question';end if;
   question_no:=p_payload->>'number';choice:=p_payload->>'choice';
   update academy_tef_listening.attempts set answers=case when choice is null then answers-question_no else jsonb_set(answers,array[question_no],to_jsonb(choice)) end,revision=revision+1 where id=a.id returning * into a;
  elsif p_action='next' then
   if jsonb_typeof(p_payload->'number') is distinct from 'number' or p_payload->>'number' !~ '^([1-9]|[12][0-9]|3[0-9]|40)$' then raise exception 'Invalid listening question';end if;
   if (p_payload->>'number')::int<>current_no then raise exception 'This listening question has ended. Continue with the current question';end if;
   if current_no=40 then raise exception 'This is the final listening question. Submit your test';end if;
   -- Only the server advances the offset; original starts/deadlines stay frozen.
   skipped:=skipped+slot_end-elapsed;
   insert into academy_tef_listening.navigation(attempt_id,skipped_seconds) values(a.id,skipped)
    on conflict(attempt_id) do update set skipped_seconds=excluded.skipped_seconds;
   update academy_tef_listening.attempts set revision=revision+1 where id=a.id returning * into a;
   current_no:=current_no+1;slot_start:=slot_end;
   slot_end:=slot_start+(paper->'questions'->(current_no-1)->>'slotSeconds')::numeric;
   question_start:=a.started_at+(slot_start-skipped)*interval '1 second';
   question_end:=case when current_no=40 then a.deadline else least(a.deadline,a.started_at+(slot_end-skipped)*interval '1 second') end;
  else
   if current_no<>40 then raise exception 'Continue to the final listening question before submitting';end if;
   update academy_tef_listening.attempts set status='completed',submitted_at=now(),result=academy_tef_listening.grade(paper,answers),revision=revision+1 where id=a.id returning * into a;
  end if;
 end if;
 if a.status='completed' then current_no:=null;question_start:=null;question_end:=null;end if;
 return jsonb_build_object('id',a.id,'testId',a.test_id,'version',a.version,'status',a.status,'answers',a.answers,'revision',a.revision,'startedAt',a.started_at,'deadline',a.deadline,'submittedAt',a.submitted_at,'serverNow',now(),
 'currentQuestion',current_no,'questionStartedAt',question_start,'questionEndsAt',question_end,
 'paper',jsonb_build_object('id',a.test_id,'version',a.version,'title',paper->>'title','seconds',paper->'seconds','questions',(
  select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('number',q->'number','kind',q->'kind','question',q->'question','options',q->'options','image',q->'image','audio',q->'audio','audioSeconds',q->'audioSeconds','previewSeconds',q->'previewSeconds','slotSeconds',q->'slotSeconds')) order by (q->>'number')::int)
  from jsonb_array_elements(paper->'questions') q)),
 'result',a.result);
end;$$;
revoke all on all functions in schema academy_tef_listening from public,anon,authenticated,service_role;
revoke all on function public.academy_tef_listening_command(text,uuid,jsonb) from public,anon,service_role;
grant execute on function public.academy_tef_listening_command(text,uuid,jsonb) to authenticated;

notify pgrst,'reload schema';
commit;
